  "legacy/05-06": {
    "id": "legacy/05-06",
    "code": "05-06",
    "marker": "continue",
    "front": "FOLLOWING UP\n“We investigated your lead on how MEDUSA is going to be transmitted. Here is what we found.”\nTake your Transmission Method report out of your Intelligence file.\nNote your answer and then turn this card over.",
    "back": "IF YOU ANSWERED...\nAnimal Contact: Read Debrief 121\nAirborne: Read Debrief 154\nSaliva: Read Debrief 135\nWaterborne: Read Debrief 213\nAfter reading the debrief entry, destroy this card.",
    "frontFlavor": "“We investigated your lead on how MEDUSA is going to be transmitted. Here is what we found.”",
    "backFlavor": ""
  },
  "legacy/05-07": {
    "id": "legacy/05-07",
    "code": "05-07",
    "marker": "continue",
    "front": "“To facilitate your continued development as junior agents, we have additional questions for you.\nAnswer legibly, and ensure that all members agree upon your responses.”",
    "back": "Decide as a group, then fill in 1 bubble per question.\nStrongly Disagree\nStrongly Agree\n5. We are superior to others who have the same role as us. 1 2 3 4 5\n6. We find it easy to motivate those reluctant to comply. 1 2 3 4 5\n7. We find it easy to complete multiple objectives at once. 1 2 3 4 5\nAfter answering, put this card into your Personnel file.",
    "frontFlavor": "“To facilitate your continued development as junior agents, we have additional questions for you.\nAnswer legibly, and ensure that all members agree upon your responses.”",
    "backFlavor": ""
  },
